import math

def is_prime(n):
    if n <= 1 or (n % 2 == 0 and n > 2):
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def sum_of_digits(n):
    return sum(int(digit) for digit in str(n))

def find_largest_prime_sum_of_digits(lst):
    largest_prime = None
    largest_prime_sum = 0

    for num in lst:
        if is_prime(num) and (largest_prime is None or largest_prime_sum < sum_of_digits(num)):
            largest_prime = num
            largest_prime_sum = sum_of_digits(num)

    return largest_prime_sum
```

